syntax:
Return type function_name() { 
  Object obj; //object construction
  return obj; //compiler can apply RVO/NRVO here if appropriate
}

code_example:
#include <iostream>
#include <string>
struct LargeObject {
  std::string data;
  LargeObject(const std::string& d) : data(d) { std::cout << "LargeObject constructor called\n"; }
  LargeObject(const LargeObject& other) : data(other.data) { std::cout << "LargeObject copy constructor called\n"; }
  LargeObject(LargeObject&& other) noexcept : data(std::move(other.data)) { std::cout << "LargeObject move constructor called\n"; }
  ~LargeObject() { std::cout << "LargeObject destructor called\n"; }
};
LargeObject createLargeObject() {
  LargeObject obj("Hello");
  return obj;
}
int main() {
  LargeObject obj = createLargeObject();
  return 0;
}
